static unsigned int checks = 0;
static void check(bool value, const char* message)
{
    if (!value) throw std::runtime_error(message);
    ++checks;
}

static void check_plain_ancestry(std::filesystem::path path)
{
    check(path.is_absolute(), "absolute fixture root required");
    for (;;)
    {
        const DWORD attributes = GetFileAttributesW(path.c_str());
        check(attributes != INVALID_FILE_ATTRIBUTES && !(attributes & FILE_ATTRIBUTE_REPARSE_POINT),
              "missing or reparse fixture ancestor");
        const auto parent = path.parent_path();
        if (parent == path) break;
        path = parent;
    }
}

class LockedFixture
{
    HANDLE handle_ = INVALID_HANDLE_VALUE;
public:
    LockedFixture(const std::filesystem::path& path, const unsigned char* expected, size_t bytes)
    {
        check_plain_ancestry(path.parent_path());
        handle_ = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr,
                              OPEN_EXISTING, FILE_FLAG_OPEN_REPARSE_POINT, nullptr);
        check(handle_ != INVALID_HANDLE_VALUE, "cannot acquire fixture read lock");
        try
        {
            BY_HANDLE_FILE_INFORMATION info{};
            check(GetFileInformationByHandle(handle_, &info) &&
                  !(info.dwFileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)),
                  "fixture must be a regular file");
            LARGE_INTEGER size{};
            check(GetFileSizeEx(handle_, &size) && size.QuadPart == static_cast<LONGLONG>(bytes),
                  "fixture size differs from reviewed bytes");
            std::vector<unsigned char> actual(bytes);
            DWORD count = 0;
            check(ReadFile(handle_, actual.data(), static_cast<DWORD>(bytes), &count, nullptr) &&
                  count == bytes && std::memcmp(actual.data(), expected, bytes) == 0,
                  "fixture bytes differ from source-reviewed original");
        }
        catch (...) { CloseHandle(handle_); handle_ = INVALID_HANDLE_VALUE; throw; }
    }
    LockedFixture(const LockedFixture&) = delete;
    LockedFixture& operator=(const LockedFixture&) = delete;
    ~LockedFixture() { if (handle_ != INVALID_HANDLE_VALUE) CloseHandle(handle_); }
};

static void verify_abi()
{
    static_assert(sizeof(void*) == 8);
    static_assert(sizeof(zonetool::h1::XModel) == 680);
    static_assert(sizeof(zonetool::h1::XModelSurfs) == 56);
    static_assert(sizeof(zonetool::h1::XSurface) == 264);
    static_assert(sizeof(zonetool::h1::GfxPackedVertex) == 32);
    static_assert(sizeof(zonetool::h1::XRigidVertList) == 16);
    static_assert(sizeof(zonetool::iw7::XModel) == 736);
    static_assert(sizeof(zonetool::iw7::XSurface) == 256);
    static_assert(offsetof(zonetool::h1::XModel, numBones) == 8);
    static_assert(offsetof(zonetool::h1::XModel, scale) == 16);
    static_assert(offsetof(zonetool::h1::XModel, lodInfo) == 128);
    static_assert(offsetof(zonetool::h1::XModel, numLods) == 512);
    static_assert(offsetof(zonetool::h1::XModel, radius) == 544);
    static_assert(offsetof(zonetool::h1::XModel, bounds) == 548);
    static_assert(offsetof(zonetool::h1::XModelSurfs, partBits) == 20);
    static_assert(offsetof(zonetool::h1::XSurface, verts0) == 24);
    static_assert(offsetof(zonetool::h1::XSurface, rigidVertLists) == 72);
    static_assert(offsetof(zonetool::h1::XSurface, partBits) == 228);
    static_assert(offsetof(zonetool::h1::GfxPackedVertex, normal) == 24);
    static_assert(offsetof(zonetool::iw7::GfxPackedVertex, selfVisibility) == 12);
}

static void observe(const std::filesystem::path& root)
{
    verify_abi();
    LockedFixture model_guard(root / "xmodel/paris_h1_original_cube.xmb", model_bytes, sizeof(model_bytes));
    LockedFixture surface_guard(root / "xsurface/paris_h1_original_cube_lod0.xsb", surface_bytes, sizeof(surface_bytes));
    // Exact byte locks remain held until after parsers, converted objects and
    // their allocators are destroyed. Only these positive inputs reach C++.
    auto& search_paths = zonetool::filesystem::get_search_paths();
    search_paths.clear();
    zonetool::filesystem::add_path(root.string(), true);
    zonetool::zone_memory parser_memory(1024 * 1024);
    utils::memory::allocator converted_memory;
    zonetool::h1::xmodel model_parser;
    zonetool::h1::xsurface surface_parser;
    auto* source_model = model_parser.parse("paris_h1_original_cube", &parser_memory);
    auto* source_group = surface_parser.parse("paris_h1_original_cube_lod0", &parser_memory);
    check(source_model && source_group, "production parser returned null");
    check(source_model->numBones == 1 && source_model->numRootBones == 1 &&
          source_model->numLods == 1 && source_model->numsurfs == 1, "parsed model counts");
    check(source_model->boneNames && source_model->boneNames[0] == 0, "unresolved token changed");
    const auto* bone_name = model_parser.get_script_string(&source_model->boneNames[0]);
    check(bone_name && std::strcmp(bone_name, "tag_origin") == 0, "parser did not retain bone string");
    check(source_model->materialHandles && source_model->materialHandles[0] &&
          std::strcmp(source_model->materialHandles[0]->name, "paris_h1_original_material") == 0,
          "parsed material named reference");
    check(source_model->lodInfo[0].modelSurfs &&
          std::strcmp(source_model->lodInfo[0].modelSurfs->name, source_group->name) == 0,
          "parsed LOD named reference");
    check(source_group->numsurfs == 1 && source_group->surfs, "parsed surface count");
    const auto& original = source_group->surfs[0];
    check(original.flags == 0 && original.vertCount == 24 && original.triCount == 12 &&
          original.rigidVertListCount == 1 && original.subdivLevelCount == 0,
          "parsed ordinary rigid surface counts");
    check(original.verts0.packedVerts0 && original.triIndices && original.rigidVertLists,
          "parsed geometry pointers");
    check(original.rigidVertLists[0].boneOffset == 0 && original.rigidVertLists[0].vertCount == 24 &&
          original.rigidVertLists[0].triCount == 12 && !original.rigidVertLists[0].collisionTree,
          "parsed rigid root coverage");

    // These are the exact production functions. No hand-constructed input structs.
    auto* model = zonetool::h1::converter::iw7::xmodel::convert(source_model, converted_memory);
    auto* group = zonetool::h1::converter::iw7::xsurface::convert(source_group, converted_memory);
    check(model && group && model != reinterpret_cast<void*>(source_model) &&
          group != reinterpret_cast<void*>(source_group), "conversion allocation");
    check(model->numBones == 1 && model->numRootBones == 1 && model->numClientBones == 0 &&
          model->numsurfs == 1 && model->numLods == 1 && model->hasLods, "converted model counts");
    check(model->scale == 1.0f && std::memcmp(&model->bounds, &source_model->bounds, 24) == 0 &&
          model->radius == source_model->radius, "converted model bounds/scale");
    check(model->boneNames == source_model->boneNames && model->boneNames[0] == 0,
          "converter must preserve unresolved bone token");
    check(model->baseMat == reinterpret_cast<zonetool::iw7::DObjAnimMat*>(source_model->baseMat),
          "production bind pose alias");
    check(model->boneInfo == reinterpret_cast<zonetool::iw7::XBoneInfo*>(source_model->boneInfo),
          "production bone bounds alias");
    check(model->materialHandles && model->materialHandles[0] &&
          std::strcmp(model->materialHandles[0]->name, source_model->materialHandles[0]->name) == 0,
          "converted material name");
    check(!model->materialHandles[0]->techniqueSet, "material name stub unexpectedly complete");
    check(model->lodInfo[0].numsurfs == 1 && model->lodInfo[0].surfIndex == 0 &&
          model->lodInfo[0].dist == 1000.0f && model->lodInfo[0].modelSurfs &&
          std::strcmp(model->lodInfo[0].modelSurfs->name, group->name) == 0,
          "converted LOD named reference");
    check(!model->lodInfo[0].modelSurfs->surfs, "named LOD reference is not linked geometry");
    check(!model->physicsAsset && !model->physicsFXShape && !model->proceduralBones,
          "unsupported model features unexpectedly present");
    check(group->numsurfs == 1 && group->surfs, "converted surface count");
    const auto& converted = group->surfs[0];
    check(converted.flags == zonetool::iw7::SURF_FLAG_SELF_VISIBILITY &&
          converted.vertCount == 24 && converted.triCount == 12 &&
          converted.rigidVertListCount == 1 && converted.subdivLevelCount == 0,
          "converted ordinary surface profile");
    check(converted.verts0.packedVerts0 &&
          static_cast<void*>(converted.verts0.packedVerts0) !=
          static_cast<void*>(original.verts0.packedVerts0), "ordinary vertex allocation");
    check(!converted.blendVerts && converted.blendVertSize == 0 && !converted.lmapUnwrap &&
          !converted.subdiv && !converted.tensionData && !converted.tensionAccumTable,
          "rigid conversion introduced optional streams");
    check(std::memcmp(converted.blendVertCounts, original.blendVertCounts,16) == 0 &&
          std::memcmp(converted.partBits, original.partBits,32) == 0 &&
          std::memcmp(group->partBits, source_group->partBits,32) == 0,
          "blend counts/part bits");
    check(converted.triIndices == reinterpret_cast<zonetool::iw7::Face*>(original.triIndices) &&
          converted.rigidVertLists == reinterpret_cast<zonetool::iw7::XRigidVertList*>(original.rigidVertLists),
          "production topology/rigid aliases");
    for (unsigned int i = 0; i < 24; ++i)
    {
        const auto& a = original.verts0.packedVerts0[i];
        const auto& b = converted.verts0.packedVerts0[i];
        check(std::memcmp(a.xyz,b.xyz,12) == 0 && a.color.packed == b.color.packed &&
              a.texCoord.packed == b.texCoord.packed && a.normal.packed == b.normal.packed &&
              a.tangent.packed == b.tangent.packed, "converted vertex fields changed");
        // Literal result of the pinned self-visibility codec for {0,0,1,0}.
        check(b.selfVisibility.packed == 0x01FE0100, "real self-visibility codec result");
    }
    // No pointer addresses or local paths in emitted evidence. No dump call exists.
    std::cout << "{\"schema\":\"iw7.h1-parser-converter-observation/1\",\"checks\":" << checks
              << ",\"production_parsers_executed\":true,\"production_converters_executed\":true"
              << ",\"declaration_adapter\":true,\"whole_zonetool_application\":false"
              << ",\"bone_name_observed\":\"tag_origin\",\"bone_engine_token_resolved\":false"
              << ",\"material_reference\":\"paris_h1_original_material\",\"material_complete\":false"
              << ",\"lod_named_reference_linked\":false,\"vertices_checked\":24"
              << ",\"dump_executed\":false,\"ff_built\":false,\"render_verified\":false"
              << ",\"retail_h1_compatibility\":false}\n";
}

int wmain(int argc, wchar_t** argv)
{
    try
    {
        check(argc == 2, "exactly one absolute fixture directory required");
        std::filesystem::path root(argv[1]);
        check(root.is_absolute() && root == root.lexically_normal(), "normalized fixture root required");
        observe(root);
        return 0;
    }
    catch (const std::exception& error)
    {
        std::cerr << "fixture refused/failed: " << error.what() << '\n';
        return 1;
    }
}
